TP.register({id:"lp10-g2",lp:10,grade:"2",mode:"curriculum",checks:9,nextGrade:"3rd grade",build(E){const F=E.F;const LAST_BELL="Priya had been on the setup crew since Monday. By Friday morning the yard was finally ready. Long tables ran down both sides of the grass. Each one had a strip of bunting clipped along the front. Priya walked the row one last time and straightened the name cards. Her own card sat beside a clay bird. She had spent three weeks on it. At noon the last bell rang. The gate swung open. The whole school poured out onto the grass at once. Priya stood behind her table with her hands behind her back. She tried to look like she was not watching. But she watched every single person who stopped.";const BAND="A marching band has nobody out in front waving a stick. The players are all moving. Most of them cannot see each other. So a band holds together by sound instead. The bass drum lays down a steady beat. The beat is low and loud. Every player steps on it. Sound travels about a thousand feet in one second. That seems quick. But a long band can stretch far enough. The players at the back hear the drum a little late. Good bands fix this by watching the feet ahead of them as well as listening.";const BUNTING="Bunting is the line of little flags that gets strung across a yard. A maker cuts the flags out of light cloth, usually in the shape of a triangle, and folds the top edge of each one over a long strip of tape. Then the whole line runs through a sewing machine in one pass, so the tape closes over every flag at once. A twenty foot line holds about twenty flags, spaced a hand's width apart. Cloth bunting can be washed and rolled up and used again for years, which is why most schools buy it once instead of cutting new paper flags every time.";const FABLE="A squirrel found a long red ribbon lying on the grass after the school show. This is the finest thing in the whole wood, she said. Then she carried it up to her branch. All afternoon she wound the ribbon around and around herself. So that nobody else could take any of it. Then the wind came up the hill. The ribbon caught the wind like a sail. It pulled hard. The squirrel had to let the whole thing go. She could not keep her grip on the branch. A wren had been watching all day. She picked the ribbon up out of the grass. She wove it into her nest. There it kept three eggs warm all spring.";const WORDS=["marched","cheer","sparkle","crowd","thumb","straight","unpack","gladly","should","afternoon","clatch","frisp"];const ic=(e,px)=>(F.icon||F.pic2)(e,px)||e;const passage=(title,text)=>`<h3 style="margin:14px 0 4px;color:var(--sea)">${title}</h3><p class="passage" style="font-size:1.45rem;line-height:1.65;max-width:none">${text}</p>`;const pills=(...w)=>`<div class="row center" style="margin-top:18px;gap:18px">${w.map(x=>`<span class="pill" style="font-size:1.4rem">${x}</span>`).join("")}</div>`;const WRITE_DIR="Write on your paper. When you finish, hold it up or read it to your teacher.";const DISP="font-family:var(--font-display);font-weight:800";const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>{const eye=(x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`;const blush=(x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`;const smile=(x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`;return eye(cx-sp,cy)+eye(cx+sp,cy)+blush(cx-sp-7,cy+9)+blush(cx+sp+7,cy+9)+smile(cx,cy+9,mw||4)});const n1=v=>Math.round(v*10)/10;const at=(x,y,k,inner)=>`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})">${inner}</g>`;const INK="#6B4A3C",PINK="#F4899E",GOLDL="#FBD873",SKYB="#9FD6F0",MINT="#B8E3A8",LILAC="#C9A6EC",CREAM="#FBF1E4";const PARTY=[PINK,GOLDL,SKYB,MINT,LILAC];const frame=(w,h)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;function lab(x,y,t,sz,c){return`<text x="${x}" y="${y}" font-size="${sz||22}" font-family="Andika,sans-serif" font-weight="700" fill="${c||"var(--ink)"}" text-anchor="middle">${t}</text>`}function candleShape(x,y,s,c){const k=s/26;return`<g transform="translate(${n1(x)} ${n1(y+2*k)}) scale(${n1(k)})">${candleArt(c)}</g>`}function candleArt(c){return`<image href="data:image/webp;base64,${window.TP_CANDLE}" x="-9.3" y="-33" width="18.6" height="62"/>`}const candleSvg=(w,c)=>`<svg viewBox="0 0 ${w} ${Math.round(w*2.3)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a candle">${candleShape(w*.5,w*1.15,w*.86,c)}</svg>`;function pairRow(e,n,alt){const pitch=104,inPair=44,pairs=Math.floor(n/2),odd=n%2;const w=40+pairs*pitch+(odd?pitch*.8:0)+30,h=130;let b=frame(w,h);for(let p=0;p<pairs;p++){const x=40+p*pitch;b+=`<rect x="${x-6}" y="30" width="${inPair+42}" height="68" rx="16" fill="none" stroke="var(--line)" stroke-width="2.6" stroke-dasharray="6 5"/>`;b+=F.picXY(x+16,64,e,40)+F.picXY(x+16+inPair,64,e,40)}if(odd){const x=40+pairs*pitch;b+=F.picXY(x+16,64,e,40)}return`<svg viewBox="0 0 ${w} ${h}" width="${Math.min(w,900)}" role="img" aria-label="${alt}">${b}</svg>`}function bannerShapes(){const st=`stroke="${INK}" stroke-width="3.6" stroke-linejoin="round"`;const w=980,h=250;let b=frame(w,h);b+=`<polygon points="110,56 172,176 48,176" fill="${PINK}" ${st}/>`+lab(110,212,"A",26);b+=`<polygon points="252,70 374,70 346,176 280,176" fill="${SKYB}" ${st}/>`+lab(313,212,"B",26);const pent=[[0,-62],[59,-19],[36,50],[-36,50],[-59,-19]].map(p=>`${(520+p[0]).toFixed(1)},${(118+p[1]).toFixed(1)}`).join(" ");b+=`<polygon points="${pent}" fill="${GOLDL}" ${st}/>`+lab(520,212,"C",26);const hex=[0,1,2,3,4,5].map(i=>{const a=Math.PI/6+i*Math.PI/3;return`${(710+62*Math.cos(a)).toFixed(1)},${(118+62*Math.sin(a)).toFixed(1)}`}).join(" ");b+=`<polygon points="${hex}" fill="${MINT}" ${st}/>`+lab(710,212,"D",26);b+=`<path d="M840 92 l50 -26 l50 26 v62 l-50 26 l-50 -26 Z" fill="${LILAC}" ${st}/>`;b+=`<path d="M840 92 l50 26 l50 -26 M890 118 v62" fill="none" ${st}/>`+lab(890,212,"E",26);return`<svg viewBox="0 0 ${w} ${h}" width="940" role="img" aria-label="Five shapes painted on the show banner: A is a pink triangle, B is a blue four sided shape, C is a gold five sided shape, D is a green six sided shape, and E is a purple box drawn so you can see three of its square faces.">${b}</svg>`}const LOG=F.table(["Day","Things brought in","Weather"],[["Monday","12","clear"],["Tuesday","18","windy"],["Wednesday","9","rain"],["Thursday","21","clear"]],{caption:"Setup Crew Log"});const MADE_TABLE=F.table(["What the class did","How many"],[["Songs learned","7"],["Games played","4"],["Skits written","5"]],{caption:"Our Year in Three Lines"});const STOPS=[{id:1,title:"Show Word Flip",short:"Word Flip",parts:[{std:["RF.2.3"],kind:"words",words:WORDS,n:12,dur:85,dir:"Read each word out loud. The last two are made-up words. Just sound them out.",desc:"reading words with digraphs, blends, vowel teams, r-controlled vowels, a silent letter, a prefix, a suffix, and an irregular spelling",key:["Read each word in order. clatch and frisp are made-up words: listen for the short a with tch, and for the fr blend with the sp ending.","Watch for: the -ed ending said as /t/ with r-controlled ar and ch (marched), the ee team (cheer), the -le ending with ar (sparkle), the ow diphthong (crowd), the silent b (thumb), a three-letter blend with aigh (straight), the prefix un- (unpack), the suffix -ly (gladly), an irregular spelling (should), and a three-syllable compound with oo (afternoon)."]}]},{id:2,title:"Odd or Even",short:"Odd Even",parts:[{std:["2.OA.C.3"],n:5,dur:110,dir:"Look at the two trays. Answer out loud. Write the last two answers on your paper.",desc:"deciding whether a group of up to 20 is odd or even by pairing, and writing an even number as a sum of two equal addends",html:()=>`<p class="big" style="margin-top:0">The crew lines things up in twos so nothing gets missed.</p>`,fig:()=>F.row([pairRow("star",16,"Sixteen stars grouped into pairs, with no star left over"),"Tray 1"]),fig2:()=>F.row([pairRow("flag",13,"Thirteen flags grouped into pairs, with one flag left over at the end"),"Tray 2"]),qs:["Look at Tray 1. Count by 2s. How many stars, and is that odd or even?","Look at Tray 2. How many flags, and is that odd or even? How do you know?","There are 14 chairs in the front row. Odd or even? How do you know without a picture?","Write an equation that shows 18 as two equal addends.","Is 20 odd or even? Write it as two equal addends."],key:["16, and 16 is even. Every star is in a pair and none is left over. Counting by 2s goes 2, 4, 6, 8, 10, 12, 14, 16","13, and 13 is odd. There are 6 pairs and one flag standing alone at the end","Even. 14 splits into 7 pairs with none left over, and counting by 2s lands exactly on 14","9 + 9 = 18","Even. 10 + 10 = 20"]}]},{id:3,title:"The Last Bell",short:"Last Bell",parts:[{title:"Read the Story",std:["RF.2.4"],kind:"read",n:110,label:"words read correctly",dur:85,dir:"Read the story out loud. Use your best reading voice.",desc:"a 110-word grade-level story read aloud",html:()=>`<p class="passage g2-flu">${LAST_BELL}</p>`,key:["110 words. Mark each missed word and each self-correction on the passage in the record sheet.","Note pace and expression in your notes."]},{title:"Story Questions",std:["RL.2.1"],n:5,dur:85,dir:"Your teacher can read the story again if you need it. Then answer each question out loud.",desc:"asking and answering who, what, why, and how questions about key details in a story",html:()=>`<details class="look-back g2-story" open style="margin-bottom:10px"><summary>The Last Bell (click to open or close the story)</summary><p class="passage" style="font-size:1.45rem;line-height:1.65;max-width:none">${LAST_BELL}</p></details>`,after:view=>{const d=view.querySelector("details.g2-story");if(d&&view.querySelector(".g2-flu"))d.open=false},qs:["Who had been working on the setup crew all week?","What did she straighten on her last walk down the row?","Why did her own name card matter to her?","How did she act once the whole school came out onto the grass?","Your turn. Ask a question about the story. Start with who, what, where, when, why, or how."],key:["Priya","The name cards","It sat next to the clay bird she had worked on for three weeks, so it marked her own piece in the show","She kept still behind her own table, hands tucked away, trying to hide how closely she was watching","Asks a question that is about this story and starts with a question word (for example: When did the gate open? Where were the tables set up?)."]}]},{id:4,title:"Trays of Little Cakes",short:"Arrays",parts:[{std:["2.OA.C.4"],n:4,dur:110,dir:"Look at each tray. Answer out loud and write each equation on your paper.",desc:"finding the total in a rectangular array by adding equal rows, and writing the total as a sum of equal addends",html:()=>`<p class="big" style="margin-top:0">The little cakes come out of the kitchen on trays, in neat rows.</p>`,fig:()=>F.row([F.array(4,5,"cake"),"Tray 1"]),fig2:()=>F.row([F.array(3,4,"cake"),"Tray 2"]),qs:["Tray 1. How many rows, and how many in each row? How many little cakes in all?","Write an equation for Tray 1 that adds the rows.","Tray 2. How many little cakes in all? Write the equation that adds the rows.","The kitchen sends out one more tray with 5 rows of 3. Write the equation and the total."],key:["4 rows with 5 in each row, 20 little cakes in all","5 + 5 + 5 + 5 = 20","12 little cakes. 4 + 4 + 4 = 12","3 + 3 + 3 + 3 + 3 = 15"]}]},{id:5,title:"How a Band Stays Together",short:"The Band",parts:[{std:["RI.2.1"],n:5,dur:90,dir:"Read about marching bands. Then answer each question out loud.",desc:"asking and answering what, why, and how questions about an informational text the student read",html:()=>passage("How a Band Stays Together",BAND),qs:["What does a marching band use instead of somebody waving a stick out front?","Why can the players not simply watch one another?","How fast does the text say sound travels?","Why do the players at the back of a long band hear the drum late?","Your turn. Ask a question about bands or about sound. Start with who, what, where, when, why, or how."],key:["Sound. The low, loud, steady beat of the bass drum","Because they are all in motion and the ones behind cannot see the ones in front","About a thousand feet every second","The band stretches so far that the sound needs extra time to reach the back","Asks a question that is about the topic and starts with a question word (for example: How heavy is a bass drum? Why do bands march in lines?)."]}]},{id:6,title:"Fix the Program Note",short:"Program",parts:[{title:"Say It Right",std:["L.2.1"],n:6,dur:95,dir:"Say each answer out loud.",desc:"spoken grammar items (irregular past tense, irregular plural, reflexive pronoun, adverb, word order, joining two sentences)",qs:["Today we sing the show song. Last year we ____.","One foot, two ____.","Omar fixed the gate all by ____.","Which word fits? The crowd cheered ____. Is it loud or loudly?","Mix-up! Put these words in order to make a sentence: <b>hung / the banner / over the gate</b>","Join these two sentences with the word <b>so</b>: The band played one more song. We stayed late."],key:["sang","feet","himself","loudly","The banner hung over the gate.","The band played one more song, so we stayed late."]},{title:"Write It Right",std:["L.2.2"],n:6,dur:90,dir:"Write each answer on your paper and hold it up.",desc:"written conventions (capital letters in names and places, an apostrophe for a possessive and a contraction, a comma in a letter greeting, spelling two patterns)",qs:["Fix this sentence: <b>on friday we carried the tables out to maple yard</b>","The banner belongs to the class. Write the missing word: <b>the ____ banner</b>","This is the start of a letter. Write it and add the missing mark: <b>Dear Priya</b>","Write <b>did not</b> as one short word with an apostrophe.","Listen. Write the word your teacher says.","Listen. Write the second word your teacher says."],key:["On Friday we carried the tables out to Maple Yard. (capital O to start, capital F on the day name, capital M and capital Y in the place name, and a period)","class’s (apostrophe before the s)","Dear Priya, (comma after Priya)","didn’t (apostrophe where the o of not comes out)","Say: “Cheer. The whole yard gave one long cheer.” The student writes cheer (ee team).","Say: “Garden. We walked out to the garden.” The student writes garden (two syllables, ar then en)."]}]},{id:7,title:"Measure the Ribbon",short:"Measure",parts:[{std:["2.MD.A.1"],n:6,dur:115,dir:"Look at the ruler. Answer out loud. For the last one, get a real ruler and measure.",mats:["a ruler"],desc:"measuring length with a ruler, choosing the right measuring tool for the job, and measuring a real object with a ruler",html:()=>`<p class="big" style="margin-top:0">Every name card gets a ribbon tied to it, and every ribbon has to be the same length.</p>`,fig:()=>F.row(F.ruler({length:6,unit:"inches",item:5,itemLabel:"ribbon"})),qs:["How long is the ribbon on the ruler?","Where does the end of the ribbon have to sit for the measurement to be right?","You need the length of the whole yard. Would you pick a 12-inch ruler, a yardstick, or a measuring tape? Why?","You need the width of one name card. Which tool would you pick?","A banner is 3 feet long. Is it longer than a yardstick, shorter than a yardstick, or exactly the same?","Now get a real ruler. Pick up a pencil or a spoon and measure it. How long is it?"],key:["5 inches","At the 0 mark, the very left end. Starting at the 1 would make it come out an inch short","A measuring tape. It is long and it bends, so one person can run it the whole way without lifting and marking over and over","The 12-inch ruler. The card is small, and a ruler has small marks","Exactly the same. A yardstick is 3 feet long","Picks up the ruler, lines one end of the object up with the 0, reads the nearest whole inch or centimeter, and says the unit"]}]},{id:8,title:"The Bake Sale Table",short:"Money",parts:[{std:["2.MD.C.8"],n:5,dur:90,dir:"Look at the coins. Solve on your paper. Say your answer out loud.",desc:"solving word problems with quarters, dimes, nickels, and pennies, using cent and dollar symbols",html:()=>`<p class="big" style="margin-top:0">The class runs a little table at the show, and everything on it costs coins.</p>`,fig:()=>F.row([F.coins(["Q","D","D","N","P","P","P"]),"What is in the tin"]),qs:["Count the coins in the tin. How much money is that? Use the cent sign.","A paper flag costs 35¢. You pay with 2 quarters. How much change do you get back?","Rae has 3 dimes and 4 nickels. How much money does she have?","A little cake costs 75¢. You have 2 quarters and 2 dimes. Do you have enough? If not, how much more do you need?","Write one dollar and twenty-five cents using a dollar sign."],key:["53¢ (25 + 10 + 10 + 5 + 1 + 1 + 1 = 53)","15¢ back (2 quarters is 50¢, and 50 - 35 = 15)","50¢ (3 dimes is 30¢, 4 nickels is 20¢, and 30 + 20 = 50)","No. You have 70¢ (50 + 20), so you need 5¢ more","$1.25"]}]},{id:9,title:"What We Made Graph",short:"Graph",parts:[{title:"Read the Picture Graph",std:["2.MD.D.10"],n:4,dur:90,dir:"Look at the picture graph. Answer out loud.",desc:"reading a single-unit picture graph and answering how many more and how many in all",html:()=>`<p class="big" style="margin-top:0">The class counted up everything that went on the tables.</p>`,fig:()=>F.row(F.pictograph({title:"What went on the tables",cats:["Paintings","Clay animals","Books"],vals:[8,5,6],icon:"star",each:1})),key:["Point to the key line at the bottom first. Each picture stands for one thing. Ask: How many clay animals went on the tables? (5)","Ask: Which row has the most? (Paintings, with 8)","Ask: How many more paintings than books? (2 more. 8 - 6 = 2)","Ask: How many things went on the tables in all? (19. 8 + 5 + 6 = 19)"]},{title:"Draw the Bar Graph",std:["2.MD.D.10"],n:3,dur:60,dir:"Use the table. Draw a bar graph on your paper and hold it up.",desc:"drawing a single-unit bar graph from a table and answering a question about it",fig:()=>F.row(MADE_TABLE),qs:["Draw a bar graph on your paper. Make one bar for each line, and make each bar as many squares tall as the number says. Label both sides.","Which bar came out the tallest?","How many more songs than games?"],key:["A bar graph with three labeled bars: 7, 4 and 5 squares tall, a label on each bar, and numbers up the side. The bars do not need to be neat, but they do need to match the table","Songs learned, at 7","3 more (7 - 4 = 3)"]}]},{id:10,title:"Shapes on the Banner",short:"Shapes",parts:[{std:["2.G.A.1"],n:6,dur:80,dir:"Look at the five shapes on the banner. Answer out loud. Draw the last one on your paper.",desc:"naming shapes by their number of sides and angles, including quadrilaterals, pentagons, hexagons, and cubes, and drawing a shape to a rule",fig:()=>F.row(bannerShapes()),qs:["Count the sides and the angles on shape A. What is it called?","Count the sides on shape B. What is the name for any shape with that many sides?","Count the angles on shape C. What is it called?","Count the sides on shape D. What is it called?","Shape E is solid, not flat. Its faces are all equal squares. What is it called?","Draw a shape with 4 equal sides and 4 square corners. What is it called?"],key:["3 sides and 3 angles. A triangle","4 sides. Any shape with 4 sides is a quadrilateral","5 angles. A pentagon","6 sides. A hexagon","A cube. It has 6 equal square faces","A square. Count it correct when the drawing is closed, has 4 sides that look about equal, and has square corners"]}]},{id:11,title:"The Squirrel and the Ribbon",short:"The Fable",parts:[{std:["RL.2.2"],n:3,dur:80,dir:"Read the fable out loud. Then answer out loud.",desc:"recounting a fable and naming its lesson",html:()=>passage("The Squirrel and the Ribbon",FABLE),qs:["Retell this fable in your own words. Tell what happened first, next, and last.","What is the lesson of this fable?","Which part of the fable shows that lesson best? Tell me why you picked it."],key:["A retelling with the main events in order: the squirrel finds the ribbon, she takes it up to her branch and wraps it around herself so nobody else can have any, the wind catches it and she has to let it go, and a wren takes it and builds it into a nest for her eggs. Count it correct when the big events are there in the right order, in the student's own words","Any sensible lesson about hoarding, such as: keeping a thing to yourself does not make it worth more, or a thing is worth more when it is used than when it is hidden away. Accept a lesson the student can tie back to the story","Most students pick the moment the wind takes the ribbon, or the moment the wren builds it into the nest. Count it correct when the student names a part and gives a reason that links it to the lesson they just gave"]}]},{id:12,title:"Workshop Report",short:"Report",parts:[{title:"Listen Up",std:["SL.2.2"],n:4,dur:65,read:BUNTING,dir:"Listen first. Then answer your teacher's questions out loud.",desc:"recounting and describing key ideas and details from a text read aloud",html:()=>`<p class="huge" aria-hidden="true">${ic("ear",96)}</p><p class="big" style="text-align:center">Listen carefully. Your teacher will read a report from the workshop that makes bunting.</p>`,key:["Ask: What is bunting? (the line of little flags that gets strung across a yard)","Ask: Describe how the flags get fastened to the line. (the top edge of each flag folds over a long strip of tape, and the whole line goes through a sewing machine in one pass, so every flag is caught at once)","Ask: About how many flags are on a twenty foot line, and how far apart are they? (about twenty flags, a hand's width apart)","Say: Tell me two more things you learned. (any two: the flags are cut from light cloth, they are usually triangles, cloth bunting can be washed, it rolls up and lasts for years, schools buy it once instead of cutting new paper flags)"]},{title:"Tell Me About It",std:["SL.2.4"],n:4,label:"checks met",dur:65,dir:"Tell about it out loud. Say what happened first, next, and last.",desc:"telling about an experience in order, with facts and details, in clear complete sentences",html:()=>`<p class="big">Tell me about a time you finished something you had been working on for a long time. What was it? How long did it take? What happened when it was finally done?</p>${pills("First","Next","Last")}`,key:["Tells what happened in an order that makes sense","Gives facts that fit (what it was, how long, who was there)","Uses describing details (how it looked, felt, or sounded)","Speaks in complete sentences, loud and clear enough to hear"]}]},{id:13,title:"The Crew Log",short:"Crew Log",parts:[{std:["W.2.8"],n:4,dur:95,dir:"Use the log to answer. Say the first two answers out loud. Write number 3 on your paper and hold it up. Then say number 4.",desc:"gathering information from a provided log and recalling information from experience to answer questions",html:()=>`<p class="big" style="margin-top:0">The setup crew wrote down how many things came in each day, and what the weather was like.</p>`,fig:()=>F.row([candleSvg(60,GOLDL),"One candle"],LOG),qs:["Use the log. Which day did the most things come in?","Which days were clear?","A friend asks, “Did more things come in on Tuesday or on Wednesday?” Write one sentence that answers your friend. Use the log.","Now use what you remember. Think of a time you kept track of something over a few days. What was it, and what did you notice?"],key:["Thursday, with 21","Monday and Thursday","The sentence says Tuesday and uses the numbers from the log (Tuesday had 18 and Wednesday had 9).","Tells one thing remembered from really keeping track of something, in a sentence that answers the question (for example: I counted the birds at the feeder, and there were more on the cold days.)."]}]},{id:14,title:"Year End Writing",short:"Write",parts:[{wk:"opinion",alt:{group:"write",label:"Morning or Afternoon",icon:"💬",hint:"Give two reasons"},std:["W.2.1"],n:5,label:"checks met",dur:115,dir:WRITE_DIR,desc:"an opinion piece with two reasons, linking words, and a closing sentence",html:()=>`<p class="big">Next year, should the class show be in the morning or at the end of the day? Write what you think. Give two reasons, use the words because, and or also to join them up, and finish with a sentence that wraps it up.</p>${pills("I think","because","also","So")}`,key:["Introduces the topic: when next year's show should be (W.2.1)","States a clear opinion, morning or end of the day (W.2.1)","Supplies a first reason that actually supports the opinion (W.2.1)","Supplies a second, different reason (W.2.1)","Uses a linking word such as because, and or also, and ends with a closing sentence (W.2.1)"]},{wk:"facts",alt:{group:"write",label:"How to Set Up",icon:"📖",hint:"Facts and one definition"},std:["W.2.2"],n:5,label:"checks met",dur:150,dir:WRITE_DIR,desc:"an informative piece with an introduction, facts, a definition, and a closing sentence",html:()=>`<p class="big">Teach somebody how to set up the yard. It is for a class show. They have never done it. Introduce what you are explaining. Give at least three facts. Say how it is done. Explain what one of the words means. End with a closing sentence.</p>${pills("Setting up means","First","You also need","In the end")}`,key:["Introduces the topic in the first sentence: setting up the yard for a show (W.2.2)","Gives at least three facts about how it is done, not opinions (W.2.2)","Explains what one word means, such as bunting, a name card, or the setup crew (W.2.2)","The facts are in an order a reader can follow (W.2.2)","Ends with a closing statement, not just a last fact (W.2.2)"]}]},{id:15,title:"Read the Banners",short:"Banners",parts:[{std:["RF.2.3"],n:3,dur:55,dir:"Read each line out loud. Sound out any word that is tricky.",desc:"applying grade-level phonics and word-analysis skills to decode words in text",html:()=>`<ol class="qlist" style="font-size:1.6rem;line-height:1.9"><li>The bright banners sparkled above the crowded yard.</li><li>We unpacked eight crates and straightened every chair.</li><li>The whole school marched out at noon and cheered.</li></ol>`,key:["Line 1: listen for igh in bright, the two syllables in banners, the -le ending in sparkled with the -ed said as /d/, and the ow diphthong in crowded.","Line 2: listen for the prefix un and the -ed said as /t/ in unpacked, the irregular eigh in eight, the final e in crates, and the aigh in straightened.","Line 3: listen for the wh in whole where the w is silent, the oo team in school and noon, the r-controlled ar with ch in marched, and the ee team in cheered."]}]},{id:16,title:"Numbers on the Program",short:"Place Value",parts:[{title:"Hundreds, Tens, Ones",std:["2.NBT.A.1"],n:3,dur:55,dir:"Look at the blocks. Answer out loud.",desc:"reading a three digit number as hundreds, tens and ones, including a zero in a place",html:()=>`<p class="big" style="margin-top:0">The programs come boxed. A flat is 100 programs, a rod is 10, and a cube is 1.</p>`,fig:()=>F.row(F.blocks(3,4,6)),qs:["What number do the blocks show, and what does each digit stand for?","A second box holds 706 programs. How many tens are in 706?","What number is 4 hundreds, 0 tens and 9 ones?"],key:["Say: What number do the blocks show, and what does each digit stand for? (346. The 3 is 3 hundreds, which is 300 programs. The 4 is 4 tens, which is 40. The 6 is 6 ones.)","Say: A second box holds 706 programs. How many tens are in 706? (0 tens. 706 is 7 hundreds, 0 tens and 6 ones. A student who says 70 tens is reading the whole number, so ask again for the digit in the tens place.)","Say: What number is 4 hundreds, 0 tens and 9 ones? (409)"]},{title:"Skip Count the Crates",std:["2.NBT.A.2"],n:3,dur:50,dir:"Count out loud for your teacher.",desc:"counting within 1000 by 5s, 10s and 100s from a given number",html:()=>`<p class="big" style="text-align:center">Count out loud. Keep going until you reach the number your teacher gives you.</p>`,qs:["Count by 5s from 60 up to 100.","Count by 10s from 430 up to 500.","Count by 100s from 200 up to 900."],key:["Say: Count by 5s from 60 up to 100. (60, 65, 70, 75, 80, 85, 90, 95, 100)","Say: Count by 10s from 430 up to 500. (430, 440, 450, 460, 470, 480, 490, 500)","Say: Count by 100s from 200 up to 900. (200, 300, 400, 500, 600, 700, 800, 900)","Write down the place any count broke. Crossing a hundred, as at 490 to 500, is the usual spot."]},{title:"Three Ways to Write It",std:["2.NBT.A.3"],n:3,dur:55,dir:"Write each answer on your paper and hold it up.",desc:"writing numbers to 1000 as numerals, as number names, and in expanded form",html:()=>`<p class="big" style="margin-top:0">A number can be written three ways: 235, two hundred thirty five, and 200 + 30 + 5.</p>`,qs:["Write 582 in expanded form.","Write the number name for 407.","Write the numeral for six hundred thirty."],key:["Say: Write 582 in expanded form. (500 + 80 + 2)","Say: Write the number name for 407. (four hundred seven. Four hundred and seven is fine too. Watch for four hundred seventy, which is a different number.)","Say: Write the numeral for six hundred thirty. (630. Watch for 6030, which comes from writing what you hear.)"]}]},{id:17,title:"Adding Up the Whole Show",short:"Add Subtract",parts:[{title:"Within a Thousand",std:["2.NBT.B.7"],n:3,dur:60,dir:"Solve each one on your paper. Show your work and hold it up.",desc:"adding and subtracting within 1000 and explaining what happens to the tens and hundreds",html:()=>`<ol class="qlist" style="font-size:1.6rem"><li>248 + 175</li><li>506 - 129</li></ol>`,key:["248 + 175 = 423. Any method is fine: place value, a number line, or the written algorithm.","506 - 129 = 377.","Say: In the first one, what happened to the tens? (40 and 70 make 110, which is 11 tens, so a new hundred is made and 1 ten is left in the tens place. Look for the student naming the regrouping, not just getting the number.)"]},{title:"Show Day Word Problems",std:["2.OA.A.1"],n:3,dur:65,dir:"Solve each one on your paper. Say your answer and tell how you got it.",desc:"one-step and two-step word problems within 100, with the unknown in different places",html:()=>`<p class="big" style="margin-top:0">The crew keeps a running count all day.</p>`,qs:["The crew set out 48 chairs in the morning and 27 more after lunch. How many chairs in all?","There were 92 programs. 35 were handed out before noon and 28 more after noon. How many are left?","Rae had some name cards. She wrote 16 more, and then she had 41. How many did she start with?"],key:["Say: The crew set out 48 chairs in the morning and 27 more after lunch. How many chairs in all? (75. 48 + 27 = 75.)","Say: There were 92 programs. 35 were handed out before noon and 28 more after noon. How many are left? (29. Two steps: 92 - 35 = 57, then 57 - 28 = 29. Adding 35 + 28 = 63 first and then 92 - 63 = 29 is just as right.)","Say: Rae had some name cards. She wrote 16 more, and then she had 41. How many did she start with? (25. 41 - 16 = 25. The unknown is the starting amount, which is the hardest of the three.)","Write down which problem needed a drawing or an equation and which one the student did in their head."]}]},{id:18,title:"The Clock in the Yard",short:"Time",parts:[{std:["2.MD.C.7"],n:4,dur:60,dir:"Look at the two clocks. Answer out loud. Write the third answer on your paper.",desc:"telling and writing time to the nearest five minutes, using a.m. and p.m., and knowing minutes in an hour",fig:()=>F.row([F.clock(1,15,200),"Clock A"],[F.clock(4,50,200),"Clock B"]),qs:["What time is Clock A?","What time is Clock B?","The show starts at the time on Clock A, in the afternoon. Write that time with a.m. or p.m.","How many minutes are in one hour?"],key:["Say: What time is Clock A? (1:15, said as one fifteen or quarter past one. The minute hand is on the 3, and each number is five minutes.)","Say: What time is Clock B? (4:50, said as four fifty or ten to five. The minute hand is on the 10. Watch for five fifty, which comes from reading the hour hand as the 5 it is almost touching.)","Say: The show starts at the time on Clock A, in the afternoon. Write that time with a.m. or p.m. (1:15 p.m.)","Say: How many minutes are in one hour? (60)"]}]},{id:19,title:"A Last Day Story",short:"Story",parts:[{wk:"story",std:["W.2.3"],n:4,label:"checks met",dur:75,dir:WRITE_DIR,desc:"a short narrative: events in order, details about actions and feelings, time words, and a closing",html:()=>`<p class="big">Write a short story about a last day. It can be a day you really had or one you make up. Tell what happened in order, say what the people did and how they felt, and finish it off.</p>${pills("First","Next","Then","In the end")}`,key:["Recounts a short sequence of events, not one single moment (W.2.3)","Includes details that describe actions, thoughts, or feelings (W.2.3)","Uses a time word such as first, next, then, after that, or finally to signal the order (W.2.3)","Provides a sense of closure, an ending rather than a stop (W.2.3)","A few sentences is enough. This is a short check of the shape of a narrative, not a full story."]}]},{id:20,title:"Three Sunflower Pots",short:"Plant Test",parts:[{std:["2-LS2-1"],n:3,dur:90,dir:"Read the chart. Then answer out loud.",desc:"reading the results of a plant test and planning a fair test of one thing a plant needs",html:()=>`<p class="big">The class grew sunflowers to stand on the stage for the show. Three pots were planted together and measured five weeks later.</p>
     <table class="bigTable"><tr><th>Pot</th><th>What it got</th><th>After five weeks</th></tr>
     <tr><td>A</td><td>the sunny courtyard, watered twice a week</td><td>62 centimeters, one big flower head</td></tr>
     <tr><td>B</td><td>the sunny courtyard, never watered</td><td>7 centimeters, leaves curled and dry</td></tr>
     <tr><td>C</td><td>the back of the classroom, watered twice a week</td><td>31 centimeters, thin stem, no flower</td></tr></table>
     <div class="figure">${ic("sunflower",88)}${ic("sun",88)}</div>`,qs:["Which pot was ready for the stage, and what did it get?","Pot C grew to 31 centimeters and still never flowered. Say what it was missing and why that stopped the flower.","You want to test only whether a sunflower needs water. Name two things you would keep the same, and name the one thing you would change."],key:["Pot A, 62 centimeters with one big flower head. It got both sunlight and water.","It was missing sunlight at the back of the classroom. A plant makes its food out of light, and a flower head takes a lot of food, so with only dim light it could put out a thin stem and nothing more.","Keep the same: the same seeds, the same pot, the same soil, the same sunny spot. Change only one thing: one pot watered twice a week and one pot not watered. Changing two things is not a fair test, so ask again."]},{std:["2-LS2-2"],n:2,dur:90,dir:"Draw your model on your paper. Then tell your teacher about it.",desc:"making a simple model that does the job an animal does when it pollinates plants",html:()=>`<p class="big">Beetles crawl right across the middle. They cross the big sunflower heads. Pollen catches on their backs. It rubs off again. That is on the next head they cross.</p>
     <div class="figure">${ic("ladybug",88)}${ic("sunflower",88)}</div>
     <p class="big">Draw a model you could really build out of classroom things, such as a felt pad glued on a bottle top, that would pick pollen up off one flower head by being dragged across it and leave some on the next one.</p>`,qs:["Draw your model. Label the part that the pollen catches on and show which way it is dragged.","Which animal job does your model copy, and why does it have to be dragged across the middle of the flower head rather than held above it?"],key:["Any model with a soft or fuzzy top surface and a direction of travel marked: a felt pad on a bottle top, a scrap of fleece on a block, a cotton pad on a lid. The labeled catching surface and the arrow are what to look for.","It copies a beetle crawling across a flower head. The pollen sits on the middle of the head, so the model has to touch it to pick any up. Held above, it would never touch the pollen and nothing would be carried."]}]},{id:21,title:"The Planters and the Back Field",short:"Two Places",parts:[{std:["2-LS4-1"],n:3,dur:90,dir:"Read both lists. Answer out loud.",desc:"comparing the kinds of living things found in two different habitats",html:()=>`<p class="big">The class counted living things in two places at school, twenty minutes in each.</p>
     <table class="bigTable"><tr><th>The courtyard planters</th><th>The rough field behind the school</th></tr>
     <tr><td>3 kinds of flower the class planted</td><td>6 kinds of wild plant</td></tr>
     <tr><td>1 kind of ant</td><td>4 kinds of beetle and bug</td></tr>
     <tr><td>1 kind of bee</td><td>3 kinds of bee and wasp</td></tr>
     <tr><td>1 kind of bird at the feeder</td><td>2 kinds of bird, 1 mole hill</td></tr></table>
     <div class="figure">${ic("purpleFlower",80)}${ic("butterfly",80)}</div>`,qs:["How many kinds of living things are on each list?","Which place has more different kinds, and by how many?","The planters are swept and weeded every week and the field is cut twice a year. Explain how that could make the two lists so different."],key:["The planters have 6. Three flowers, one ant, one bee and one bird. The field has 16. Six wild plants, four beetles and bugs, three bees and wasps, two birds and one mole hill.","The field, by 10 kinds. 16 take away 6 is 10.","Sweeping and weeding takes away the plants that were not planted on purpose, and most of the small animals live on those plants, so the planters stay tidy and nearly empty. The field is left alone most of the year, so many plants grow and many animals find food and cover. Listen for the link between what a place gives and what lives there."]}]},{id:22,title:"One Afternoon, or Thousands of Years",short:"Fast or Slow",parts:[{std:["2-ESS1-1"],n:3,dur:90,dir:"Read both notes. Answer out loud.",desc:"using two sources as evidence that some Earth events happen quickly and some happen slowly",html:()=>`<p class="big">Two notes about the land around the school, from two different places.</p>
     <table class="bigTable"><tr><th>Where it came from</th><th>What it says</th></tr>
     <tr><td>a letter sent home by the school office</td><td>After the heavy rain, the soft ground at the far corner of the field dropped into a hole about as wide as a hula hoop in one afternoon. The corner is now fenced off.</td></tr>
     <tr><td>a plaque on the hill path</td><td>The hill behind the school is the worn down stump of a far taller hill. Wind and water have been taking it down for thousands of years.</td></tr></table>`,qs:["Which note tells about a change that happened in one afternoon?","Which note tells about a change that has taken thousands of years?","Name one more change to the land that happens quickly, and one that happens slowly."],key:["The letter from the school office, the ground dropping into a hole in one afternoon.","The plaque on the hill path, the hill worn down over thousands of years.","Quick: a flood, a rockfall, a bank falling in, a tree pushed over in a storm. Slow: a river cutting a canyon, a cliff wearing back, soil building up year by year. The answer has to name a change to the land, not just a kind of weather."]},{std:["2-ESS2-3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling where water is found on Earth and whether it is solid or liquid",html:()=>`<p class="big">There is water all over the school grounds, and some of it you cannot see.</p>
     <div class="figure">${ic("drop",80)}${ic("cloud",80)}${ic("snowflake",80)}</div>`,qs:["Name three places on or near these school grounds where you would find water.","Most of the water on Earth is in the ocean and it is salty. Name two places on Earth where the water is fresh instead.","Sort these four into solid water and liquid water: snow on a mountain top, the water in the park pond, the ice in a lunch cooler, the rain running down a window."],key:["Any three: the drinking fountain pipe, the park pond, a puddle, the creek, the clouds, in the soil, inside the trees and the planter flowers.","Any two: a river, a lake, a pond, a stream, rain, snow or ice on a mountain, water under the ground.","Solid: the snow on the mountain top and the ice in the cooler. Liquid: the pond water and the rain running down the window."]}]},{id:23,title:"Holding the Planter Soil, and a Map of the Grounds",short:"The Land",parts:[{std:["2-ESS2-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"comparing two things put in place to stop water from washing the soil away",html:()=>`<p class="big">The courtyard planters sit on a slight slope, and rain washes soil out of them onto the path. Two fixes were tried and the soil swept off the path was weighed.</p>
     <table class="bigTable"><tr><th>What was on the planters</th><th>Soil swept off the path in a month</th></tr>
     <tr><td>bare soil</td><td>7 kilograms</td></tr>
     <tr><td>a layer of bark chips over the soil</td><td>1 kilogram</td></tr>
     <tr><td>a line of bricks along the low edge</td><td>4 kilograms</td></tr></table>`,qs:["Which fix kept the most soil in the planters?","How do you know, using the numbers in the chart?","The bricks stay put for years and the bark chips have to be topped up every spring. Which would you choose, and why?"],key:["the layer of bark chips over the soil","Only 1 kilogram had to be swept off the path with the bark chips, 4 kilograms with the bricks, and 7 kilograms with bare soil. The reason must come from the numbers.","Either choice works with a reason: bark chips because they keep much more soil in, or bricks because 4 kilograms is still better than 7 and nobody has to top them up. Listen for the reason, not the choice."]},{std:["2-ESS2-2"],n:3,dur:90,dir:"Draw on your paper and hold it up.",desc:"making a model of an area that shows the shapes of the land and the bodies of water in it",html:()=>`<p class="big">Make your own model map of the school grounds. Put in the hill behind the school, the flat field, the park pond, and the creek that runs along the far fence. Add a key that says which is which.</p>
     <div class="figure">${ic("map",88)}${ic("mountain",88)}${ic("board",88)}</div>`,qs:["Draw your model map with the hill, the flat field, the pond and the creek on it.","Show me your key. Which parts are land and which parts are water?","Name one thing your model shows well and one thing it leaves out."],key:["All four on the page and told apart by shape or color: the hill as a bump or as rings, the field left flat, the pond as a closed shape, the creek as a line.","Points to each part and reads the key. The key is what makes this a model and not just a picture.","Shows well: where things are, which is high and which is low, which way the creek runs, the shape of the pond. Leaves out: how high the hill really is, how deep the pond is, the trees, the buildings, the colors. Naming anything a flat drawing cannot carry counts, because knowing what a model leaves out is part of using one."]}]},{id:24,title:"Sorting the Prop Box",short:"Materials",parts:[{std:["2-PS1-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"describing materials by properties you can see or feel and sorting them into groups",html:()=>`<p class="big">Four things out of the prop box for the show, and what the class noticed about each one.</p>
     <table class="bigTable"><tr><th>Item</th><th>Material</th><th>What the class noticed</th></tr>
     <tr><td>a star for the backdrop</td><td>foil</td><td>thin, bends easily, shiny, catches the light</td></tr>
     <tr><td>a hand sign</td><td>cardboard</td><td>stiff, dull, bends slowly, tears if you fold it twice</td></tr>
     <tr><td>a lantern pane</td><td>glass</td><td>hard, smooth, you can see right through it</td></tr>
     <tr><td>a curtain tie</td><td>felt</td><td>soft, bends easily, fuzzy</td></tr></table>`,qs:["Sort the four items into a hard group and a group that bends easily.","Two of them do something with light. Which two, and what is the difference between what they do?","Name one more property from the chart you could sort these four by, and sort them by it."],key:["Hard: the glass lantern pane. Bends easily: the foil star and the felt tie. The cardboard sign is stiff and bends slowly, so either group can be argued for it as long as the student says why.","The foil star and the glass pane. The foil is shiny and bounces the light back at you, and the glass lets the light go straight through so you can see what is behind it.","Any property that can be seen or felt and that really splits the four: shiny or dull, tears or does not, soft or hard, see through or not. The groups have to match the property named."]},{std:["2-PS1-2"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"using test data to choose the material that suits a job",html:()=>`<p class="big">The class needs a material for the banner that will hang right across the back of the stage. Three materials were each hung for a day, loaded at the corners, and looked at from the back row.</p>
     <table class="bigTable"><tr><th>Material</th><th>Still hanging after a day</th><th>Readable from the back row</th></tr>
     <tr><td>thin paper</td><td>no, it tore at the corners</td><td>yes</td></tr>
     <tr><td>plastic sheet</td><td>yes</td><td>no, the letters shone and blurred</td></tr>
     <tr><td>cotton sheet</td><td>yes</td><td>yes</td></tr></table>`,qs:["Which material should the banner be made of?","Which two pieces of the chart make you sure?","The plastic sheet hung there all day without a problem. Why is it still the wrong choice for this job?"],key:["the cotton sheet","It was still hanging after a day and it was readable from the back row. Both columns have to be used, not just one.","The letters shone and blurred, so nobody at the back could read it. A banner that stays up but cannot be read has not done the job the banner is for."]}]},{id:25,title:"Taken Apart, Heated, Cooled",short:"Heat and Cold",parts:[{std:["2-PS1-3"],n:2,dur:75,dir:"Answer out loud. You may draw if it helps.",desc:"telling how a thing built from a few pieces can be taken apart and built into something new",html:()=>`<p class="big">The stage frame is made of 8 poles and 10 clips. After the show the class unclipped all of it. They laid the poles along the back wall.</p>
     <div class="figure">${ic("board",88)}${ic("box",88)}</div>`,qs:["The frame is gone. Are the poles and clips gone too? What is along the back wall now?","Build something new in your head out of those 8 poles and 10 clips. What is it, and how do the pieces go together?"],key:["No. All 8 poles and all 10 clips are still there. They are the same pieces, just not clipped together as a stage frame any more.","Any real thing from 8 poles and 10 clips: a doorway arch, a sign stand, a frame for a puppet theater, a shelter, a bean frame for the garden, a goal. Listen for how the pieces join, because that is the evidence the same set of pieces made something different."]},{std:["2-PS1-4"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"arguing with evidence that some heating and cooling changes can be undone and some cannot",html:()=>`<p class="big">Two things happened in the school kitchen on the day of the show.</p>
     <table class="bigTable"><tr><th>What happened</th></tr>
     <tr><td>A block of wax for the stage lanterns was warmed in a tin and ran into a clear pool.</td></tr>
     <tr><td>A bowl of cake batter was baked in a hot oven and came out as a firm cake.</td></tr></table>
     <div class="figure">${ic("cake",80)}${ic("pan",80)}</div>`,qs:["Let the tin of melted wax stand until it is cold. What happens to it?","Let the cake go completely cold. Does it turn back into runny batter?","Which of the two changes can be undone, and what is your evidence?"],key:["It goes solid again and is a block of wax, in the shape of the tin.","No. It stays a firm cake. Going cold does not make it batter again.","The wax change can be undone. The evidence is that the wax goes solid again when it cools and melts again when it is warmed, while the baked cake never goes back to batter however cold it gets. Listen for the student using what happened, not just saying yes or no."]}]},{id:26,title:"The Banner That Curls",short:"Solve It",parts:[{std:["K-2-ETS1-1"],n:2,dur:60,dir:"Read the note. Answer out loud.",desc:"naming a problem people want to fix and asking a question about it",html:()=>`<p class="passage">The paper banner for the show is taped up. It is taped to the wall. The tape is at its two top corners. Within an hour the bottom edge has curled up. The middle has sagged forward. So you can read only half of it. That is from the audience. The class keeps taping it back. It keeps curling again.</p>`,qs:["What is the problem the class wants to fix? Say it in one sentence.","Ask one question that would help you fix it."],key:["The banner curls at the bottom and sags in the middle, so it cannot be read. Naming the curling and sagging, not the retaping, is the problem.","Any real question: how long is the banner, how heavy is the paper, how far apart is the tape, is the wall smooth or rough, is there anything along the top to hang it from. A statement is not a question, so ask once more."]},{std:["K-2-ETS1-2"],n:2,dur:75,dir:"Draw on your paper and hold it up.",desc:"drawing a design and telling how its shape does the job",html:()=>`<p class="big">Draw something that would hold the banner flat and readable all through the show. Think hard about its shape.</p>
     <div class="figure">${ic("board",88)}${ic("star",88)}</div>`,qs:["Draw your fix.","Tell me how the shape of what you drew holds the banner flat."],key:["Any design that could really work: a thin stick or rod taped along the top and another along the bottom, a frame all the way round, tape or clips at many points instead of two, a string through the top edge, the banner backed onto card.","The shape is the part being checked. Something like: a straight stick cannot curl so the paper taped to it cannot either, a weight along the bottom pulls it straight, the frame holds all four edges at once, backing it on card makes the whole thing stiff."]},{std:["K-2-ETS1-3"],n:2,dur:60,dir:"Read the chart. Answer out loud.",desc:"comparing test results from two designs built for the same problem",html:()=>`<p class="big">Both fixes were tried for a whole rehearsal.</p>
     <table class="bigTable"><tr><th>Fix</th><th>Times it curled or sagged</th><th>Words readable from the back row</th></tr>
     <tr><td>a thin stick taped along the top and the bottom</td><td>0</td><td>all 9</td></tr>
     <tr><td>tape at six points along the top</td><td>4</td><td>5 of 9</td></tr></table>`,qs:["Which fix worked better?","How do you know? Use both columns."],key:["the thin stick taped along the top and the bottom","It never curled or sagged and all 9 words could be read from the back row, while the tape at six points curled or sagged 4 times and only 5 of the 9 words could be read. Both columns have to be used."]}]},{id:27,title:"School Then and Now",short:"Long Ago",parts:[{std:["HSS-2.1"],n:3,dur:75,dir:"Read the four lines. Answer out loud.",desc:"telling things that happened long ago from things that happened in the last day or two",html:()=>`<p class="big">Four lines from the display in the school hall.</p>
     <table class="bigTable"><tr><th>Line</th><th>What it says</th></tr>
     <tr><td>1</td><td>Children at this school once wrote on small slates with chalk and wiped them clean at the end of each lesson.</td></tr>
     <tr><td>2</td><td>Yesterday the class painted the backdrop for the show.</td></tr>
     <tr><td>3</td><td>Long ago, many children here left school early to work, and the school year was shorter than it is now.</td></tr>
     <tr><td>4</td><td>This morning the chairs were set out in rows for the audience.</td></tr></table>`,qs:["Which two lines tell about things that happened long ago?","Which two tell about things that happened in the last day or two?","Pick one of the long ago lines and say what is different about school now."],key:["Lines 1 and 3, writing on slates and leaving school early to work with a shorter school year.","Lines 2 and 4, painting the backdrop yesterday and setting out the chairs this morning.","Either one: children write in books or type now and keep what they wrote instead of wiping it off; children stay at school longer and the school year is longer now."]}]},{id:28,title:"Where Things Are at School",short:"School Map",parts:[{std:["HSS-2.2"],n:4,dur:90,dir:"Look at the map. Answer out loud.",desc:"giving an exact place on a map with a letter and a number, and using north, south, east, west and between",html:()=>`<p class="big">The school grounds, drawn in nine squares. North is at the top.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ic("mountain",46)} the hill path</td><td>${ic("tree",46)} back field</td><td>${ic("drop",46)} park pond</td></tr>
     <tr><th>B</th><td>${ic("books",46)} library</td><td>${ic("star",46)} hall and stage</td><td>${ic("soup",46)} lunch room</td></tr>
     <tr><th>C</th><td>${ic("purpleFlower",46)} courtyard planters</td><td>${ic("bus",46)} bus loop</td><td>${ic("soccerBall",46)} play yard</td></tr></table>
     <p class="big">${ic("compass",56)} North is up, south is down, east is to the right, west is to the left.</p>`,qs:["Give the exact square the hall and stage are in, using the letter and the number.","What is directly south of the hall and stage?","Is the library east or west of the lunch room?","Start at the hill path in square A1. Move two squares east. Where do you land?"],key:["B2","the bus loop, in square C2","west. The library is in B1 and the lunch room is in B3, so the library is to the left, which is west.","the park pond, in square A3. East is to the right, so A1 to A2 is the back field and A2 to A3 is the park pond. (HSS-2.2)"]}]},{id:29,title:"Rules, Money and the Bake Sale",short:"Rules and Money",parts:[{std:["HSS-2.3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling who makes rules at each level here, and how another country chooses a leader differently",html:()=>`<p class="big">A school is run by rules from more than one place: the school itself, the school board the city votes for, and the state.</p>
     <div class="figure">${ic("flag",80)}${ic("books",80)}</div>`,qs:["A school board decides things for all the schools in a city, and the people of the city vote for it. Name one thing a school board might decide.","Who makes the laws for the whole country we live in? A school board, or the people we vote for in Congress?","In some other countries the leader is a king or a queen who was born into the job. In our country, how do we get our leaders?"],key:["Any real answer: when the school year starts and ends, which buildings get built or fixed, how the money is spent, who runs the schools, what is taught.","the people we vote for in Congress. A school board decides only for its own schools.","We vote for them. Any answer that says the people choose their leaders by voting counts."]},{std:["HSS-2.4"],n:3,dur:90,dir:"Read the price list. Answer out loud.",desc:"telling goods from services, spending a set amount, and naming a producer and a consumer",html:()=>`<p class="big">The bake sale table at the show, run to pay for next year's seeds and paint.</p>
     <table class="bigTable"><tr><th>What is on offer</th><th>Price</th></tr>
     <tr><td>a slice of cake</td><td>40 cents</td></tr>
     <tr><td>a bread roll</td><td>25 cents</td></tr>
     <tr><td>a cup of lemonade</td><td>20 cents</td></tr>
     <tr><td>someone to carry your tray to a seat</td><td>15 cents</td></tr></table>
     <div class="figure">${ic("cake",72)}${ic("lemon",72)}</div>`,qs:["Three things on this list are goods and one is a service. Which one is the service, and how do you know?","You have 50 cents. Name two things you could buy with it, and say what you give up.","The class baked the cake and sold it to you. Which of you is the producer and which is the consumer?"],key:["Someone carrying your tray to a seat. It is work somebody does for you, not a thing you keep.","Any pair at 50 cents or less: a roll and lemonade is 45 cents, two lemonades is 40 cents, cake and the carrying is 55 cents and is too much. The giving up is the part to listen for.","The class is the producer, because it baked the cake. You are the consumer, because you buy and eat it."]}]},{id:30,title:"Two Who Made a Difference",short:"Made a Difference",parts:[{std:["HSS-2.5"],n:3,dur:90,dir:"Read about him. Answer out loud.",desc:"telling what one person from the past did, naming a character strength, and saying how it helped others",html:()=>`<p class="passage">George Washington Carver was born into slavery. It was in Missouri. He was set free as a small child. He wanted to learn so badly. He walked miles to a school. That school would take him. Later he worked his way through college. He became a scientist who studied plants. Farmers near him grew cotton. They grew it year after year. Their soil wore out. Their crops failed. Carver showed them something. They could plant peanuts and sweet potatoes. That put the goodness back in the soil. Then he found hundreds of uses for those crops. So farmers could sell them. He gave his findings away free. He taught poor farmers on a wagon. He drove it from farm to farm.</p>
     <div class="figure">${ic("peanut",80)}${ic("sprout",80)}</div>`,qs:["What did George Washington Carver show the farmers near him?","Which word fits him best from what you read: generous, careless, or selfish? Say why.","Name one way his work made a difference to other people."],key:["That planting peanuts and sweet potatoes put the goodness back in soil worn out by cotton, and that those crops had hundreds of uses.","generous. Any reason taken from the text: he gave his findings away free, he drove a wagon from farm to farm to teach poor farmers.","Any answer from the text: farmers got crops that grew again in worn out soil, farmers had new things to sell, poor farmers were taught for nothing."]}]}];const LEVELUPS={1:{id:"L1",title:"Level Up: Long Show Words",std:["RF.3.3"],needs:["RF.2.3"],n:3,dir:"Read each long word out loud.",html:()=>`<div style="text-align:center">${["celebration","musician","remember"].map(w=>`<p class="huge" style="font-size:clamp(2.4rem,8vw,4.4rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["celebration (cel-e-bra-tion, with tion saying shun)","musician (mu-si-cian, with cian saying shun)","remember (re-mem-ber, three syllables with er at the end)"]},2:{id:"L2",title:"Level Up: Odd and Even Rules",std:["3.OA.D.9"],needs:["2.OA.C.3"],n:3,dir:"Answer out loud. Tell how you know.",html:()=>`<ol class="qlist"><li>Add two even numbers, like 6 + 8. Is the answer odd or even? Is that always true?</li><li>Add two odd numbers, like 7 + 9. Is the answer odd or even? Is that always true?</li><li>Every number in this list is a multiple of 4: 4, 8, 12, 16, 20. What do you notice about all of them?</li></ol>`,key:["14, and it is even. Two evens always make an even, because each one splits into pairs with nothing left over, so the total does too","16, and it is even. Two odds always make an even, because the one left over from each of them pairs up with the other","They are all even. Every multiple of 4 is also a multiple of 2, so it can always be split into pairs"]},3:{id:"L3",title:"Level Up: Show Me the Words",std:["RL.3.1"],needs:["RL.2.1"],n:2,dir:"Answer out loud. Then read the words from the story that show your answer.",html:()=>`<p class="passage" style="font-size:1.35rem;line-height:1.6">${LAST_BELL}</p><ol class="qlist"><li>How do you know Priya cared a lot about her own piece? Read the part of the story that shows it.</li><li>How do you know the yard had taken days to get ready? Read the part that shows it.</li></ol>`,key:["Says she had put weeks of work into it and could not stop watching people look at it, and reads the line about the clay bird she had spent three weeks on, or the last line about trying to look like she was not watching","Says the work had run all week, and reads the opening line about being on the crew since Monday and the yard finally being ready by Friday"]},4:{id:"L4",title:"Level Up: Rows Times Columns",std:["3.OA.A.1"],needs:["2.OA.C.4"],n:3,dir:"Answer out loud. Write each one as a multiplication.",html:()=>`<div class="figure">${F.array(4,5,"cake")}</div><ol class="qlist"><li>Write this tray as a multiplication, not an addition. What does each number stand for?</li><li>What does 3 x 6 mean? Say it with trays and little cakes.</li><li>Two trays each hold 4 rows of 5. Write one multiplication for the whole lot.</li></ol>`,key:["4 x 5 = 20. The 4 is the number of rows and the 5 is how many are in each row","3 groups of 6, which is 3 trays with 6 little cakes on each one, 18 in all","8 x 5 = 40, or 2 x 20 = 40. Both are right as long as the student can say what each number stands for"]},5:{id:"L5",title:"Level Up: Prove It",std:["RI.3.1"],needs:["RI.2.1"],n:2,dir:"Answer out loud. Then read the words from the text that show your answer.",html:()=>`<p class="passage" style="font-size:1.35rem;line-height:1.6">${BAND}</p><ol class="qlist"><li>How do you know the players cannot rely on their eyes alone? Read the part of the text that shows it.</li><li>How do you know the problem gets worse the longer the band is? Read the part that shows your answer.</li></ol>`,key:["Says they are moving and cannot all see one another, and reads the line about the players all moving and most of them not being able to see each other","Says the sound needs time to travel, so distance costs time, and reads the line about a long band stretching far enough that the back hears the drum a little late"]},6:{id:"L6",title:"Level Up: Grown-Up Grammar",std:["L.3.1"],needs:["L.2.1"],n:3,dir:"Say each answer out loud.",html:()=>`<ol class="qlist"><li>One drum is loud. A whole band is ____ than one drum.</li><li>Of all the tables in the yard, Priya's was the ____ one. Use the word near.</li><li>Join these two sentences with the word <b>although</b>: The rain started. The band kept playing.</li></ol>`,key:["louder (the comparative form)","nearest (the superlative form of near)","Although the rain started, the band kept playing. (Or: The band kept playing although the rain started.)"]},7:{id:"L7",title:"Level Up: To the Nearest Half Inch",std:["3.MD.B.4"],needs:["2.MD.A.1"],n:3,dir:"Look at the ruler. Answer out loud.",html:()=>`<div class="figure">${F.ruler({length:6,unit:"inches",item:3.5,itemLabel:"ribbon",parts:4})}</div><ol class="qlist"><li>How long is this ribbon, to the nearest half inch?</li><li>How many little marks are there between one whole inch and the next?</li><li>The crew cut ribbons of 3 inches, 3 and a half inches, 4 inches and 3 and a half inches. If you put an X above each length on a line plot, which length would have two X marks?</li></ol>`,key:["Three and a half inches. The end of the ribbon lands on the middle mark between the 3 and the 4","3 little marks, which cut the inch into 4 equal spaces. The middle one of the three is the half inch mark","The three and a half inch length, because the crew cut that one twice"]},9:{id:"L9",title:"Level Up: A Bigger Scale",std:["3.MD.B.3"],needs:["2.MD.D.10"],n:3,dir:"Answer out loud.",html:()=>`<div class="figure">${F.barGraph({title:"Programs printed each day",cats:["Mon","Tue","Wed"],vals:[20,35,15],max:40,step:5})}</div><ol class="qlist"><li>Each line up the side is worth 5. How many programs were printed on Tuesday?</li><li>How many more were printed on Tuesday than on Wednesday?</li><li>How many were printed in all three days together?</li></ol>`,key:["35","20 more (35 - 15 = 20)","70 (20 + 35 + 15 = 70)"]},10:{id:"L10",title:"Level Up: Sorting the Four-Sided Ones",std:["3.G.A.1"],needs:["2.G.A.1"],n:3,dir:"Answer out loud.",html:()=>`<ol class="qlist"><li>A square, a rectangle and a rhombus all belong to one big group. What is the group called?</li><li>What do all the shapes in that group share?</li><li>Name one thing a square has that a plain rectangle does not have to have.</li></ol>`,key:["Quadrilaterals","They all have 4 straight sides and 4 angles, and they are all closed","All four sides the same length. A rectangle only has to have square corners and opposite sides equal"]}};const PASSAGE_STD=["RL.2.1","RI.2.1","RL.2.2","RF.2.4","RF.2.3","RL.3.1","RI.3.1","RF.3.3","2-LS2-1","2-LS2-2","2-LS4-1","2-ESS1-1","2-ESS2-1","2-ESS2-2","2-ESS2-3","2-PS1-1","2-PS1-2","2-PS1-3","2-PS1-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-2.1","HSS-2.2","HSS-2.3","HSS-2.4","HSS-2.5"];let chartOn={},pvVal=["",""];function chartHtml(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${chartOn[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function pvTable(){let h=`<tr><th>Hundreds</th><th>Tens</th><th>Ones</th></tr>`;pvVal.forEach((v,r)=>{if(r&&!v)return;h+="<tr>";for(let i=0;i<3;i++){const k=v.length-(3-i);h+=`<td>${k>=0?v[k]:""}</td>`}h+="</tr>"});return h}function pvHtml(){const inp=(i,t)=>`<label class="pv-in">${t}<input type="text" inputmode="numeric" maxlength="3" data-pv="${i}" value="${pvVal[i]}" autocomplete="off"></label>`;return inp(0,"Type a number")+inp(1,"Second number (if you need one)")+`<div class="tool-scroll"><table class="pv" id="pvTable">${pvTable()}</table></div><p class="small">Type a number up to 999. Each digit goes in its place.</p>`}function coinHtml(){return`<div class="figure" style="gap:12px;flex-wrap:wrap;justify-content:center">`+[["Q","25¢"],["D","10¢"],["N","5¢"],["P","1¢"]].map(c=>`<div>${F.coin(c[0])}<p class="fig-label">${c[1]}</p></div>`).join("")+`</div><p class="small">The quarter is 25 cents, the dime is 10, the nickel is 5, and the penny is 1.</p>`}const STARTERS={"W.2.1":["I think the show should be ____.","One reason is ____.","Also, ____.","So that is why ____."],"W.2.2":["Setting up means ____.","First, ____.","You also need ____.","In the end, ____."],"W.2.8":["The log says ____.","On Tuesday ____.","The most things came in on ____.","I remember ____."],"W.2.3":["On the last day, ____.","First ____.","Then ____.","In the end ____."]};function sentHtml(st){const k=st&&st.parts&&st.parts[0]&&st.parts[0].std&&st.parts[0].std[0]||"W.2.1";return`<ul class="starters">${(STARTERS[k]||STARTERS["W.2.1"]).map(x=>`<li>${x}</li>`).join("")}</ul>`}let tpsBlk=[0,0,0];function tpsMatSvg(h,t,o){return F.blocks(h,t,o)}function tpsBlkHtml(){const b=(k,t)=>`<button class="chip" data-tb="${k}">${t}</button>`;return`<div class="blk-row">${b("h+","Add a hundred")}${b("h-","Take a hundred")}${b("t+","Add a ten")}${b("t-","Take a ten")}${b("o+","Add a one")}${b("o-","Take a one")}</div><div class="blk-row">${b("to","Trade 10 ones for a ten")}${b("th","Trade 10 tens for a hundred")}${b("bt","Break a ten into ones")}${b("bh","Break a hundred into tens")}${b("x","Clear")}</div><div class="tool-scroll" style="text-align:center">${tpsBlk[0]+tpsBlk[1]+tpsBlk[2]?tpsMatSvg(tpsBlk[0],tpsBlk[1],tpsBlk[2]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${tpsBlk[0]} hundreds, ${tpsBlk[1]} tens, and ${tpsBlk[2]} ones on the mat.</p>`}function tpsBlkDo(k){const MAX=[9,19,19],i={h:0,t:1,o:2}[k[0]];if(k==="x")tpsBlk=[0,0,0];else if(k==="to"){if(tpsBlk[2]>=10&&tpsBlk[1]<19){tpsBlk[2]-=10;tpsBlk[1]++}}else if(k==="th"){if(tpsBlk[1]>=10&&tpsBlk[0]<9){tpsBlk[1]-=10;tpsBlk[0]++}}else if(k==="bt"){if(tpsBlk[1]>=1&&tpsBlk[2]<=9){tpsBlk[1]--;tpsBlk[2]+=10}}else if(k==="bh"){if(tpsBlk[0]>=1&&tpsBlk[1]<=9){tpsBlk[0]--;tpsBlk[1]+=10}}else tpsBlk[i]=Math.max(0,Math.min(MAX[i],tpsBlk[i]+(k[1]==="+"?1:-1)))}let tpsNlStart="",tpsNlHops=[],tpsNlShown={};function tpsNlSvg(){if(tpsNlStart==="")return`<p class="small">Type the number to start at.</p>`;const vals=[+tpsNlStart];tpsNlHops.forEach(d=>vals.push(vals[vals.length-1]+d));const uniq=[...new Set(vals)].sort((a,b)=>a-b),gap=72,W=Math.max(320,50+(uniq.length-1)*gap+50),X=v=>50+uniq.indexOf(v)*gap,y=150;let s=`<svg viewBox="0 0 ${W} 200" width="${W}" role="img" aria-label="Open number line">`;s+=`<line x1="16" y1="${y}" x2="${W-16}" y2="${y}" stroke="var(--ink)" stroke-width="3"/><path d="M16 ${y} l9 -6 v12 Z M${W-16} ${y} l-9 -6 v12 Z" fill="var(--ink)"/>`;tpsNlHops.forEach((d,i)=>{const a=X(vals[i]),b=X(vals[i+1]),span=Math.abs(b-a)/gap,top=y-Math.min(120,34+span*26);s+=`<path d="M${a} ${y-10} Q${(a+b)/2} ${2*top-(y-10)} ${b} ${y-10}" fill="none" stroke="var(--sea)" stroke-width="3"/>`;s+=`<text x="${(a+b)/2}" y="${top-6}" font-size="18" font-weight="700" text-anchor="middle" fill="var(--sea)">${d>0?"+":"−"}${Math.abs(d)}</text>`});uniq.forEach(v=>{const x=X(v),open=v===+tpsNlStart||tpsNlShown[v];s+=`<line x1="${x}" y1="${y-10}" x2="${x}" y2="${y+10}" stroke="var(--ink)" stroke-width="3"/>`;s+=`<g ${v===+tpsNlStart?"":`data-tv="${v}" style="cursor:pointer"`}><rect x="${x-27}" y="${y+16}" width="54" height="30" rx="8" fill="${open?"var(--surface)":"var(--sea-soft)"}" stroke="var(--sea)" stroke-width="2" ${open?"":`stroke-dasharray="4 4"`}/><text x="${x}" y="${y+32}" font-size="19" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--ink)">${open?v:"?"}</text></g>`});return s+"</svg>"}function tpsNlHtml(){const j=d=>`<button class="chip" data-tj="${d}">${d>0?"+":"−"}${Math.abs(d)}</button>`;return`<label class="pv-in">Start at<input type="text" inputmode="numeric" maxlength="3" id="tpsNlStart" value="${tpsNlStart}" autocomplete="off"></label><div class="blk-row">${[100,10,5,1].map(j).join("")}</div><div class="blk-row">${[-100,-10,-5,-1].map(j).join("")}<button class="chip" data-tj="u">Undo</button><button class="chip" data-tj="x">Clear</button></div><div class="tool-scroll" id="tpsNlBox" style="text-align:center">${tpsNlSvg()}</div><p class="small">Click a jump the student says. Each landing spot shows a ? until you click it. Click it after the student says the number.</p>`}function tpsNlBind(b,r){const box=()=>b.querySelectorAll("[data-tv]").forEach(g=>g.onclick=()=>{tpsNlShown[g.dataset.tv]=!tpsNlShown[g.dataset.tv];r()});const inp=b.querySelector("#tpsNlStart");inp.oninput=()=>{tpsNlStart=inp.value.replace(/[^0-9]/g,"");tpsNlShown={};b.querySelector("#tpsNlBox").innerHTML=tpsNlSvg();box()};b.querySelectorAll("[data-tj]").forEach(x=>x.onclick=()=>{const k=x.dataset.tj;if(k==="x"){tpsNlHops=[];tpsNlShown={}}else if(k==="u")tpsNlHops.pop();else if(tpsNlStart!==""&&tpsNlHops.length<10)tpsNlHops.push(+k);r()});box()}function tpsClockHtml(){return F.row([F.clock(8,50,170),"8:50"],[F.clock(2,15,170),"2:15, quarter past two"])+F.table(["Long hand points at","Minutes","How to say it"],[["12","00","o'clock"],["1","05","five past"],["2","10","ten past"],["3","15","quarter past"],["6","30","half past"],["9","45","quarter to the next hour"]])+`<ul class="frames"><li>Count by fives around the dial. Each numeral the long hand passes is five more minutes.</li><li>The short hand is the hour. When it sits between two numerals, say the smaller one.</li><li>a.m. is before noon. p.m. is after noon.</li></ul>`}function tpsRulerHtml(){return `<div style="text-align:center"><img alt="An inch ruler from 0 to 6 with a pencil lined up at 0. The tip of the pencil is at 5 inches." src="data:image/webp;base64,${window.TP_IMG1.wp3.inchruler}" style="width:640px;max-width:100%;height:auto"></div>`+F.table(["Mark on the ruler","How to say it"],[["the long numbered mark","a whole inch: 1, 2, 3"],["the short mark halfway between two numbers","a half inch, like 4 1/2"]])+F.table(["To measure","Use"],[["something small, like a crayon","an inch ruler"],["a desk or a door","a yardstick or a meter stick"],["something round or bendy, like a wrist","a measuring tape"]])+`<p class="small">Line the left end of the object up with the 0, then read the mark the right end lands on. Write the number with its unit.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["silent e","the e makes the vowel say its name","froze, these, bike"],["ai, ea, ee, oa, ow, oo, ew, ou","a vowel team or a diphthong","tail, seal, boat, book, flew, crowd"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, north, fur"],["un-, re-, pre-","a prefix on the front","unpack, reread, preheat"],["-y, -ly, -ful, -er, -ed, -ing","a suffix on the end","windy, slowly, helpful, jumped"],["two syllables","split the word between its parts","camp / site, sun / set"],["thought, could, through","an irregular spelling","read these as whole words"]])+`<p class="chart-note">Cover the prefix and the suffix, read the middle, then put the word back together.</p>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","the beginning: who it is about and where","First, ____."],["2. Next","the middle: what happened, in order","Next, ____."],["3. Last","the end: how it turned out","Last, ____."],["4. Lesson","what the story teaches","The story teaches ____."]])+`<ul class="frames"><li>Add a fact that fits: where, when, who or what.</li><li>Add a describing detail: how it looked, felt or sounded.</li><li>Speak in whole sentences.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={chart:{name:"120 chart",std:["2.MD.C.8","2.MD.D.10","2.NBT.A.2","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4","3.MD.A.1","3.MD.B.3","3.OA.D.8"],html:chartHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{chartOn[x.dataset.n]=!chartOn[x.dataset.n];r()})},pv:{name:"Place value chart",std:["2.MD.C.8","2.NBT.A.1","2.NBT.A.2","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.4","3.OA.A.1"],html:pvHtml,bind:b=>b.querySelectorAll("[data-pv]").forEach(x=>x.oninput=()=>{pvVal[+x.dataset.pv]=x.value=x.value.replace(/[^0-9]/g,"");b.querySelector("#pvTable").innerHTML=pvTable()})},coins:{name:"Coin values",std:["2.MD.C.8"],html:coinHtml},sent:{name:"Sentence starters",std:["W.2.1","W.2.2","W.2.3","W.2.8"],html:sentHtml},nl:{name:"Open number line",std:["2.NBT.B.7","2.OA.A.1","3.OA.D.8"],html:tpsNlHtml,bind:tpsNlBind},blocks:{name:"Hundreds, tens, and ones blocks",std:["2.NBT.A.1","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4"],html:tpsBlkHtml,bind:(b,r)=>b.querySelectorAll("[data-tb]").forEach(x=>x.onclick=()=>{tpsBlkDo(x.dataset.tb);r()})},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.2.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.2.2","SL.2.4","W.2.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","RI.2.1","RL.2.1"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.2.3","RF.2.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"chart",std:["2.OA.C.3"],msg:"On the 120 chart the even numbers line up in columns, so odd and even read straight off it. Note that the answer came from the chart, not from pairing."},{t:"chart",std:["2.MD.C.8","2.MD.D.10"],msg:"With the 120 chart the student can count on or back square by square. Note it if the totals came from counting by ones."},{t:"pv",std:["2.OA.C.4","3.OA.A.1"],msg:"The place value chart lines the digits up, which takes some of the work out of adding equal rows. Note it."},{t:"coins",std:["2.MD.C.8"],msg:"The coin value card supplies what each coin is worth, so these checks show adding and subtracting money, not knowing the coins. Note it."},{t:"sent",msg:"Sentence starters supply the opening, the linking words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["L.2.2"],msg:"Write It Right checks capitals, marks, and spelling, so the student has to do the writing. If an adult wrote, do not rate L.2.2 from this stop."},{t:"chart",std:["2.NBT.A.2"],msg:"The 120 chart prints the counting sequence in rows of ten, so a skip count read off it is supported. It also stops at 120, so it cannot help with the counts past that."},{t:"chart",std:["2.OA.A.1"],msg:"Counting forward or back along the 120 chart solves a word problem without the student choosing an operation. Note that the answer came from the chart."},{t:"pv",std:["2.NBT.A.1","2.NBT.A.3"],msg:"The place value chart sorts the digits into their places for the student, which is most of what these checks ask for. Note that the places were read off the chart."},{t:"pv",std:["2.NBT.B.7"],msg:"Lining the digits up in the place value chart does part of the regrouping work. Note it, and ask the student to say what the regrouped ten or hundred stands for."},{t:"clock",std:["2.MD.C.7","1.MD.B.3"],msg:"The clock card gives the five minute count around the dial and the a.m. and p.m. rule, so a time read with it open is supported, not independent."},{t:"ruler",std:["2.MD.A.1"],msg:"The ruler card names the inch and half inch marks and which tool to pick, so count a measurement made with it open as supported, not independent."},{t:"letters",std:["RF.2.3"],msg:"The letter and sound card lists the patterns, the prefixes and the suffixes with example words, so a word sounded out with it open is supported, not independent."},{t:"retell",std:["RL.2.2","SL.2.4","W.2.3"],msg:"The card gives the beginning, middle, end frame and asks for the lesson, so count the structure as supported and rate the content the student supplies."},{t:"qwords",std:["RL.2.1","RI.2.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.2.4","RF.2.3"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
